SELECT CASE WHEN total_female = 0 THEN 0 ELSE 100.0 * beyond_count / total_female END AS percentage
FROM (
  SELECT
    (SELECT COUNT(*) FROM Patient WHERE SEX = 'F') AS total_female,
    (SELECT COUNT(DISTINCT l.ID) FROM Laboratory l JOIN Patient p ON p.ID = l.ID WHERE p.SEX = 'F' AND l.UA > 6.5) AS beyond_count
);

SELECT CASE WHEN total=0 THEN 0 ELSE 100.0*beyond/total END AS percent
FROM (
  SELECT
    (SELECT COUNT(*) FROM Patient WHERE SEX='F') AS total,
    (SELECT COUNT(DISTINCT l.ID) FROM Laboratory l JOIN Patient p ON p.ID = l.ID WHERE p.SEX = 'F' AND l.UA > 6.5) AS beyond
);

SELECT CASE WHEN tot=0 THEN NULL ELSE (100.0*num)/tot END AS percent
FROM (
  SELECT
    (SELECT COUNT(DISTINCT ym.CustomerID) FROM yearmonth ym JOIN customers c ON ym.CustomerID=c.CustomerID WHERE c.Segment='LAM' AND ym.Consumption>46.73) AS num,
    (SELECT COUNT(*) FROM customers WHERE Segment='LAM') AS tot
);

SELECT CASE WHEN t.total=0 THEN 0.0 ELSE 100.0 * t.num / t.total END AS percent
FROM (
  SELECT
    (SELECT COUNT(DISTINCT y.CustomerID) FROM yearmonth y JOIN customers c ON y.CustomerID=c.CustomerID WHERE c.Segment='LAM' AND y.Consumption>46.73) AS num,
    (SELECT COUNT(*) FROM customers WHERE Segment='LAM') AS total
) AS t;

